namespace Commonage.Web.Media;

/// <summary>
/// Stores files under keys such as <c>originals/abc123</c>. Keys are always generated by the app,
/// never derived from user input.
/// </summary>
public interface IFileStorage
{
    Task SaveAsync(string key, Stream content, CancellationToken cancellationToken = default);

    /// <exception cref="FileNotFoundException">No file is stored under the key.</exception>
    Stream OpenRead(string key);

    /// <summary>Removes the file stored under the key. Does nothing if there is none, for example a preview that failed.</summary>
    void Delete(string key);
}

/// <summary>Stores files in a directory on the server, which should be a persistent volume in Docker.</summary>
public class LocalFileStorage(string rootPath) : IFileStorage
{
    private readonly string _root = Path.GetFullPath(rootPath);

    public async Task SaveAsync(string key, Stream content, CancellationToken cancellationToken = default)
    {
        var path = Resolve(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);

        // Write to a temporary file first so a crash never leaves a half-written file under the real key.
        var temporaryPath = path + ".uploading";
        await using (var target = File.Create(temporaryPath))
        {
            await content.CopyToAsync(target, cancellationToken);
        }

        File.Move(temporaryPath, path, overwrite: true);
    }

    // FileShare.Delete lets a curator delete a file while it is being read, for example by the preview generator or an
    // export. Linux always allows that; Windows would otherwise refuse the deletion.
    public Stream OpenRead(string key) =>
        new FileStream(Resolve(key), FileMode.Open, FileAccess.Read, FileShare.Read | FileShare.Delete, bufferSize: 4096, useAsync: true);

    public void Delete(string key)
    {
        var path = Resolve(key);
        if (File.Exists(path))
            File.Delete(path);
    }

    private string Resolve(string key)
    {
        var path = Path.GetFullPath(Path.Combine(_root, key));
        if (!path.StartsWith(_root + Path.DirectorySeparatorChar, StringComparison.Ordinal))
            throw new ArgumentException($"Storage key '{key}' points outside the storage directory.", nameof(key));
        return path;
    }
}
